<?php require 'app.php';need_school(['director','dos']);$sid=school_id();$error='';$report=null;if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();if(empty($_FILES['csv']['tmp_name'])||!is_uploaded_file($_FILES['csv']['tmp_name']))$error='Choose a CSV file first.';elseif($_FILES['csv']['size']>5*1024*1024)$error='CSV must be smaller than 5 MB.';else{$fp=fopen($_FILES['csv']['tmp_name'],'r');$head=fgetcsv($fp);$norm=array_map(fn($x)=>strtolower(trim((string)$x)),$head?:[]);$required=['admission_number','first_name','last_name'];if(array_diff($required,$norm))$error='CSV header must include admission_number, first_name, last_name.';else{$idx=array_flip($norm);$ins=db()->prepare('INSERT INTO students(school_id,admission_number,first_name,last_name,gender,date_of_birth) VALUES(?,?,?,?,?,?) ON CONFLICT(school_id,admission_number) DO NOTHING');$added=0;$skipped=0;while(($row=fgetcsv($fp))!==false){$ad=trim((string)($row[$idx['admission_number']]??''));$fn=trim((string)($row[$idx['first_name']]??''));$ln=trim((string)($row[$idx['last_name']]??''));$g=strtolower(trim((string)($row[$idx['gender']]??'not_stated')));$dob=trim((string)($row[$idx['date_of_birth']]??''));if(!in_array($g,['female','male','other','not_stated'],true))$g='not_stated';if(!$ad||!$fn||!$ln){$skipped++;continue;}try{$ins->execute([$sid,$ad,$fn,$ln,$g,$dob?:null]);if($ins->rowCount())$added++;else $skipped++;}catch(Throwable $e){$skipped++;}}fclose($fp);audit_log('students.csv_import',['added'=>$added,'skipped'=>$skipped]);$report=['added'=>$added,'skipped'=>$skipped];}}}ob_start();?><div class="panel"><h2>CSV template</h2><pre>admission_number,first_name,last_name,gender,date_of_birth
S001,Marie,Uwase,female,2010-04-15</pre><p>Required: admission_number, first_name, last_name. Optional: gender, date_of_birth. Imported students can be assigned to classes afterwards.</p><?php if($error):?><p class="danger"><?=h($error)?></p><?php endif;?><?php if($report):?><p>Added: <?=$report['added']?> · Skipped: <?=$report['skipped']?></p><?php endif;?><form method="post" enctype="multipart/form-data"><input type="hidden" name="_csrf" value="<?=h(csrf())?>"><input type="file" name="csv" accept=".csv,text/csv" required><button>Import CSV</button></form></div><?php page('Import Students',ob_get_clean());
